from functools import singledispatch

@singledispatch
def handle(node): raise TypeError(f"no handler for {type(node).__name__}")

@handle.register
def _(node: NumberNode): return node.value

@handle.register
def _(node: AddNode): return handle(node.left) + handle(node.right)
